#!/usr/bin/env python3
"""Trash empty folder trees on Drive (plan Task 13 phase 2, Eric 2026-11-03). Drive Trash keeps them 30 days.

  python3 -I tools/trash_empty.py plan              # index -> drive-index/empty_folders.csv (id,path), counts by area
  python3 -I tools/trash_empty.py run               # dry run: re-reads the CSV, prints how many would be checked
  python3 -I tools/trash_empty.py run --apply       # live check each row, trash it, log it

A candidate is the topmost folder whose whole subtree in the index holds folders only (no file of any kind), under
00_Primary_Storage_Drive, at least 4 path parts deep (ladder folders and their first level stay), not modified in the
last 14 days, not inside a code project (an ancestor holds .git, package.json, ...) and not under a build folder, with
no HEALTH name in its path and not in "Mark for deletion".
--apply re-reads each candidate live: path unchanged, not trashed, owned by me, not shared; then walks its whole live
subtree (file_moves batching): every item must be a folder, owned by me, not shared, no HEALTH name. Only then it is
trashed. Log: drive-index/trash_log_empty.csv id,status,parent,path (undo: restore from Drive Trash within 30 days).
Statuses: trashed | skip_changed | skip_shared | skip_not_empty | skip_check | error.
"""
import argparse, csv, json, sqlite3, sys, threading, time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from file_moves import BATCH, FOLDER, HEALTH, OUT, gws, live_path, page, parents_q   # noqa: E402

CSV = OUT / "empty_folders.csv"
LOG = OUT / "trash_log_empty.csv"
PRIMARY = "00_Primary_Storage_Drive"
CODE_MARK = {".git", "package.json", "pyproject.toml", "requirements.txt", "setup.py", "DESCRIPTION", ".Rproj.user"}
BUILD = {".git", "node_modules", ".venv", "venv", "__pycache__", ".pytest_cache", "dist", "build", "src", "tests"}


def ancestors(path):
    while "/" in path:
        path = path.rsplit("/", 1)[0]
        yield path


assert list(ancestors("a/b/c")) == ["a/b", "a"]


def candidate_ok(path, code_roots):
    parts = path.split("/")
    return (parts[0] == PRIMARY and len(parts) >= 4 and not HEALTH.search(path) and "Mark for deletion" not in path
            and not BUILD & set(parts) and not any(a in code_roots for a in ancestors(path + "/x")))


assert candidate_ok(f"{PRIMARY}/10_ARCHIVE/2020/Old", set()) and not candidate_ok(f"{PRIMARY}/10_ARCHIVE/2020", set())
assert not candidate_ok(f"{PRIMARY}/01_PROJECTS/_DONE/R/x", {f"{PRIMARY}/01_PROJECTS/_DONE/R"})
assert not candidate_ok(f"{PRIMARY}/10_ARCHIVE/a/node_modules/b", set()) and not candidate_ok("_MACHINE/a/b/c", set())


def plan():
    con = sqlite3.connect(f"file:{OUT / 'drive.sqlite'}?mode=ro", uri=True)
    rows = con.execute("select id, parent, name, folder, mime, modified from files").fetchall()
    path_of = {r[0]: (f"{r[3]}/{r[2]}" if r[3] else r[2]) for r in rows}
    code_roots = {r[3] for r in rows if r[2] in CODE_MARK}
    has_file = set()                     # folder ids with a non-folder anywhere below
    for fid, parent, name, folder, mime, _ in rows:
        if mime != FOLDER:
            has_file.update(a for a in ancestors(f"{folder}/{name}" if folder else name))
    cutoff = time.strftime("%Y-%m-%d", time.gmtime(time.time() - 14 * 86400))
    empty = {fid: path_of[fid] for fid, _, _, _, mime, mod in rows
             if mime == FOLDER and path_of[fid] not in has_file and (mod or "") < cutoff}
    paths = set(empty.values())
    top = sorted((p, i) for i, p in empty.items()
                 if candidate_ok(p, code_roots) and not any(a in paths for a in ancestors(p)))
    with open(CSV, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["id", "path"])
        w.writerows((i, p) for p, i in top)
    by = {}
    for p, _ in top:
        k = "/".join(p.split("/")[:2])
        by[k] = by.get(k, 0) + 1
    print(f"{len(top)} empty folder trees -> {CSV}")
    for k, n in sorted(by.items(), key=lambda x: -x[1]):
        print(f"  {n:5d} {k}")


def tree_empty(fid):
    """True if every item under fid is a folder, owned by me, not shared, no HEALTH name; False if a file is found;
    None if a reply was odd, an item is shared or not mine, or the tree passed 3,000 folders (fail closed)."""
    todo, found, scanned = [fid], {fid}, 0
    while todo:
        batch, todo, token, seen = todo[:BATCH], todo[BATCH:], None, set()
        while True:
            p = {"q": parents_q(batch), "pageSize": 1000,
                 "fields": "nextPageToken,incompleteSearch,files(id,name,mimeType,shared,ownedByMe)"}
            if token:
                p["pageToken"] = token
            got = page(gws(["list", "--params", json.dumps(p)]), seen)
            if got is None:
                return None
            files, token = got
            for f in files:
                if HEALTH.search(f["name"]) or f.get("shared") is not False or f.get("ownedByMe") is not True:
                    return None
                if f["mimeType"] != FOLDER:
                    return False
                if f["id"] in found:
                    return None
                found.add(f["id"])
                todo.append(f["id"])
            if not token:
                break
            seen.add(token)
        scanned += len(batch)
        if scanned > 3000:
            return None
    return True


def run(apply):
    rows = list(csv.DictReader(open(CSV)))
    print(f"{len(rows)} candidates in {CSV}")
    if not apply:
        return
    f = open(LOG, "a", newline="")
    w, lock = csv.writer(f), threading.Lock()

    def one(r):
        fid, path = r["id"], r["path"]
        m = gws(["get", "--params", json.dumps({"fileId": fid, "fields": "parents,trashed,shared,ownedByMe"})])
        parent = (m or {}).get("parents", [""])[0] if m and m.get("parents") else ""
        if not m or m.get("trashed") or live_path(fid) != path:
            status = "skip_changed"
        elif m.get("shared") is not False or m.get("ownedByMe") is not True:
            status = "skip_shared"
        else:
            e = tree_empty(fid)
            if e is False:
                status = "skip_not_empty"
            elif e is not True:
                status = "skip_check"
            else:
                t = gws(["update", "--params", json.dumps({"fileId": fid, "fields": "trashed"}),
                         "--json", json.dumps({"trashed": True})], tries=1)
                status = "trashed" if t and t.get("trashed") is True else "error"
        with lock:
            w.writerow([fid, status, parent, path]); f.flush()
        return status

    with ThreadPoolExecutor(8) as ex:    # candidates are disjoint topmost trees, so parallel checks cannot overlap
        res = list(ex.map(one, rows))
    print({s: res.count(s) for s in set(res)}, "->", LOG)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd", choices=["plan", "run"])
    ap.add_argument("--apply", action="store_true")
    a = ap.parse_args()
    plan() if a.cmd == "plan" else run(a.apply)

