import sqlite3,json,sys; sys.path.insert(0,'tools'); import file_moves as fm
db=sqlite3.connect('file:drive-index/drive.sqlite?mode=ro',uri=True)
def one(folder,name):
    r=db.execute("select id from files where folder=? and name=? and mime=?",(folder,name,fm.FOLDER)).fetchall(); return [x[0] for x in r]
ids={"mark":one("","Mark for deletion"),"review":one("","_TO_REVIEW"),"parked":one("00_Primary_Storage_Drive/10_ARCHIVE","_PARKED_COPIES"),"a2026":one("00_Primary_Storage_Drive/10_ARCHIVE","2026")}
print(ids)
for k,v in ids.items():
    for i in v:
        m=fm.gws(['get','--params',json.dumps({'fileId':i,'fields':'name,shared,ownedByMe,trashed,parents'})]); print(k,m, 'live path:',fm.live_path(i))
for k in ("mark","review"):
    i=ids[k][0]; todo=[i]; n={'files':0,'folders':0,'shared':0,'health':0}
    while todo:
        cur=todo.pop(); tok=None
        while True:
            p={"q":f"'{cur}' in parents and trashed = false","fields":"nextPageToken,files(id,name,mimeType,shared)","pageSize":1000}
            if tok: p["pageToken"]=tok
            r=fm.gws(["list","--params",json.dumps(p)])
            for f in r["files"]:
                if f["mimeType"]==fm.FOLDER: n['folders']+=1; todo.append(f["id"])
                else: n['files']+=1
                if f.get("shared"): n['shared']+=1
                if fm.HEALTH.search(f["name"]): n['health']+=1
            tok=r.get("nextPageToken")
            if not tok: break
    print(k,"live contents:",n)
EOF

