#!/usr/bin/env python3
"""Copy the non-DEV items of Drive's "Computers" backups into 10_ARCHIVE/2026/From_Computers/<machine>/ (plan Task 14,
Eric 2026-11-03: "fold them into my primary drive"). Drive refuses to move a backup item into My Drive (400 Bad
Request, checked 2026-11-03), so this copies. It never changes, moves or deletes an original; deciding what happens to
the originals is a separate step. A copy belongs to Eric and is not shared, even when its original is shared.

  python3 -I tools/copy_from_computers.py            # dry run: per item, what would be copied (creates nothing)
  python3 -I tools/copy_from_computers.py --apply    # copy, verify, log

Device roots come from the index (zone computers, parents of items one level below "Computers/"), each re-read live: it
must have no parent. Known limit (Codex r1 F6): a device root that was empty or absent at index time is not seen;
accepted because Drive for desktop backups are off since 2026-10-23 and the laptop is retired (no new roots).
Skipped: each machine's DEV folder (code; its home is ~/DEV + GitHub), "Chrome Syncable FileSystem", shortcuts, a top
item with no file in its live tree, a top item with a HEALTH name anywhere in its live tree, and a top item holding two
same-named items in one folder (skip_ambiguous: a copy could not keep them apart). Top items or roots that share a
name get " (2)", " (3)" ... in the destination, in id order, so they are never merged.
Consistency (Codex r1 F4): backups are quiescent (off since 10-23). Each file is still re-read live just before its copy
(same name, same single parent, same md5, not trashed, no HEALTH name), else skip_changed.
Every listing, including destination lookups, is validated with file_moves.page() (all pages; fails closed).
Log: drive-index/copy_log_computers.csv src_id,status,copy_id,dest_path. Reruns: a source logged copied is checked
live (copy in its folder, not trashed, same md5) and reported skip_done or error_prev_copy, never copied twice; a name
already in the destination with no log row is skip_collision (resolve by hand).
Statuses: copied | copied_unverified (Google-native file, no md5) | error_verify (copy id kept) | error | skip_done |
error_prev_copy | skip_changed | skip_collision; top items: skip_check | skip_health | skip_empty | skip_ambiguous.
"""
import argparse, csv, json, sqlite3, sys, threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from file_moves import FOLDER, HEALTH, OUT, gws, live_path, page, q_esc   # noqa: E402

SHORTCUT = "application/vnd.google-apps.shortcut"
A2026 = "00_Primary_Storage_Drive/10_ARCHIVE/2026"
LOG = OUT / "copy_log_computers.csv"
SKIP_ROOTS = {"Chrome Syncable FileSystem"}


def listing(q, fields="id,name,mimeType,md5Checksum"):
    """All untrashed items matching q (every page, validated), or None on any odd reply."""
    out, token, seen = [], None, set()
    while True:
        p = {"q": f"{q} and trashed = false", "pageSize": 1000,
             "fields": f"nextPageToken,incompleteSearch,files({fields})"}
        if token:
            p["pageToken"] = token
        got = page(gws(["list", "--params", json.dumps(p)]), seen)
        if got is None:
            return None
        files, token = got
        out += files
        if not token:
            return out
        seen.add(token)


def children(fid):
    return listing(f"'{fid}' in parents")


def tree(fid, limit=20000):
    """-> list of (item, relative folder path parts, parent id) under fid, or None on any odd reply / too big."""
    out, todo = [], [(fid, [])]
    while todo:
        cur, rel = todo.pop()
        kids = children(cur)
        if kids is None:
            return None
        for k in kids:
            out.append((k, rel, cur))
            if k["mimeType"] == FOLDER:
                todo.append((k["id"], rel + [k["name"]]))
        if len(out) > limit:
            return None
    return out


def suffixed(items, key):
    """{id: name} with " (2)", " (3)" ... added to repeated names, in id order."""
    seen, out = {}, {}
    for it in sorted(items, key=lambda x: x["id"]):
        n = key(it)
        seen[n] = seen.get(n, 0) + 1
        out[it["id"]] = n if seen[n] == 1 else f"{n} ({seen[n]})"
    return out


assert suffixed([{"id": "b", "n": "x"}, {"id": "a", "n": "x"}, {"id": "c", "n": "y"}], lambda i: i["n"]) == \
    {"a": "x", "b": "x (2)", "c": "y"}


def folder_in(parent, name, apply):
    """Id of the untrashed folder `name` in parent, created when apply; None in a dry run when it does not exist."""
    r = listing(f"name = '{q_esc(name)}' and '{parent}' in parents and mimeType = '{FOLDER}'", "id")
    if r is None:
        raise SystemExit(f"lookup failed for {name}: stop")
    if len(r) > 1:
        raise SystemExit(f"two folders named {name} in one parent: stop")
    if r:
        return r[0]["id"]
    if not apply:
        return None
    c = gws(["create", "--json", json.dumps({"name": name, "mimeType": FOLDER, "parents": [parent]})], tries=1)
    if not isinstance(c, dict) or "id" not in c:
        raise SystemExit(f"could not confirm the create of {name}; look for it in Drive before rerunning")
    return c["id"]


def prior_copies():
    """{src_id: copy_id} from earlier runs (copied or copied_unverified rows)."""
    if not LOG.exists():
        return {}
    return {r[0]: r[2] for r in csv.reader(open(LOG)) if len(r) >= 3 and r[1] in ("copied", "copied_unverified")}


def main(apply):
    con = sqlite3.connect(f"file:{OUT / 'drive.sqlite'}?mode=ro", uri=True)
    roots = sorted({p for (p,) in con.execute(
        "select parent from files where zone = 'computers' and folder like 'Computers/%' and folder not like 'Computers/%/%'")})
    a = con.execute("select id from files where folder = ? and name = ? and mime = ?",
                    tuple(A2026.rsplit("/", 1)) + (FOLDER,)).fetchall()
    if len(a) != 1 or live_path(a[0][0]) != A2026:
        raise SystemExit(f"{A2026} not found exactly once live: stop")
    base = folder_in(a[0][0], "From_Computers", apply)
    done = prior_copies()
    f = open(LOG, "a", newline="") if apply else None
    w, lock = (csv.writer(f) if f else None), threading.Lock()
    totals = {}

    def log(row):
        if w:
            with lock:
                w.writerow(row); f.flush()

    def count(st, n=1):
        totals[st] = totals.get(st, 0) + n

    live_roots = []
    for root in roots:
        m = gws(["get", "--params", json.dumps({"fileId": root, "fields": "id,name,parents"})])
        if not isinstance(m, dict) or not isinstance(m.get("name"), str) or "parents" in m:
            print("SKIP root (not a live device root):", root); continue
        if m["name"] not in SKIP_ROOTS:
            live_roots.append(m)
    root_names = suffixed(live_roots, lambda r: r["name"])

    for rm in live_roots:
        root, rname = rm["id"], root_names[rm["id"]]
        tops = children(root)
        if tops is None:
            print("SKIP root (listing failed):", rname); continue
        tops = [t for t in tops if t["name"] != "DEV" and t["mimeType"] != SHORTCUT]
        top_names = suffixed(tops, lambda t: t["name"])
        for top in tops:
            tname = top_names[top["id"]]
            label = f"{rname}/{tname}"
            items = [(top, [], root)] if top["mimeType"] != FOLDER else tree(top["id"])
            keys = [(tuple(rel), k["name"]) for k, rel, _ in (items or [])]
            if items is None:
                st = "skip_check"
            elif HEALTH.search(top["name"]) or any(HEALTH.search(k["name"]) for k, _, _ in items):
                st = "skip_health"
            elif not any(k["mimeType"] not in (FOLDER, SHORTCUT) for k, _, _ in items):
                st = "skip_empty"
            elif len(keys) != len(set(keys)):
                st = "skip_ambiguous"
            else:
                st = None
            if st:
                log([top["id"], st, "", label]); count(st)
                print(st, "|", label); continue
            files = [(k, rel, par) for k, rel, par in items if k["mimeType"] not in (FOLDER, SHORTCUT)]
            print(f"{'copy' if apply else 'would copy'} {len(files)} files | {label}")
            if not apply:
                count("would_copy", len(files)); continue
            mdest = folder_in(base, rname, True)
            dirs = {(): mdest}           # relative destination folder path -> id, created serially here

            def dest_for(rel):
                key = tuple(rel)
                if key not in dirs:
                    dirs[key] = folder_in(dest_for(rel[:-1]), rel[-1], True)
                return dirs[key]

            prefix = [tname] if top["mimeType"] == FOLDER else []
            jobs = []
            for k, rel, par in files:
                name = tname if top["mimeType"] != FOLDER else k["name"]
                jobs.append((k, par, name, dest_for(prefix + rel), "/".join([rname] + prefix + rel + [name])))

            def one(job):
                k, par, name, dest, path = job
                cid = ""
                if k["id"] in done:      # copied before: check that copy, never copy twice
                    c = gws(["get", "--params", json.dumps({"fileId": done[k["id"]], "fields": "parents,trashed,md5Checksum"})])
                    ok = (isinstance(c, dict) and c.get("parents") == [dest] and c.get("trashed") is False
                          and (not k.get("md5Checksum") or c.get("md5Checksum") == k["md5Checksum"]))
                    st, cid = ("skip_done" if ok else "error_prev_copy"), done[k["id"]]
                else:
                    s = gws(["get", "--params", json.dumps({"fileId": k["id"], "fields": "name,parents,md5Checksum,trashed"})])
                    taken = listing(f"name = '{q_esc(name)}' and '{dest}' in parents", "id")
                    if (not isinstance(s, dict) or s.get("name") != k["name"] or s.get("parents") != [par]
                            or s.get("trashed") is not False or s.get("md5Checksum") != k.get("md5Checksum")
                            or HEALTH.search(s.get("name", ""))):
                        st = "skip_changed"
                    elif taken is None:
                        st = "error"
                    elif taken:
                        st = "skip_collision"
                    else:
                        c = gws(["copy", "--params", json.dumps({"fileId": k["id"], "fields": "id,md5Checksum,parents"}),
                                 "--json", json.dumps({"name": name, "parents": [dest]})], tries=1)
                        cid = c.get("id", "") if isinstance(c, dict) and isinstance(c.get("id"), str) else ""
                        if not cid:
                            st = "error"
                        elif c.get("parents") != [dest]:
                            st = "error_verify"
                        elif k.get("md5Checksum"):
                            st = "copied" if c.get("md5Checksum") == k["md5Checksum"] else "error_verify"
                        else:
                            st = "copied_unverified"
                log([k["id"], st, cid, path])
                return st

            with ThreadPoolExecutor(8) as ex:   # (dest, name) pairs are unique: skip_ambiguous above guarantees it
                for st in ex.map(one, jobs):
                    count(st)
    print(totals, "->", LOG if apply else "(dry run)")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--apply", action="store_true")
    main(ap.parse_args().apply)

