            if top["name"] == "DEV" or top["mimeType"] == SHORTCUT:
                continue
            items = [(top, [])] if top["mimeType"] != FOLDER else tree(top["id"])
            label = f"{rname}/{top['name']}"
            if items is None:
                st = "skip_check"
            elif HEALTH.search(top["name"]) or any(HEALTH.search(k["name"]) for k, _ in items):
                st = "skip_health"
            elif not any(k["mimeType"] not in (FOLDER, SHORTCUT) for k, _ in items):
                st = "skip_empty"
            else:
                st = None
            if st:
                log([top["id"], st, "", label]); totals[st] = totals.get(st, 0) + 1
                print(st, "|", label); continue
            files = [(k, rel) for k, rel in items if k["mimeType"] not in (FOLDER, SHORTCUT)]
            print(f"{'copy' if apply else 'would copy'} {len(files)} files | {label}")
            if not apply:
                totals["would_copy"] = totals.get("would_copy", 0) + len(files); continue
            mdest = folder_in(base, rname, True)
            dirs = {}                    # relative folder path -> dest id, created in order

            def dest_for(rel):
                key = tuple(rel)
                if key not in dirs:
                    parent = mdest if not rel else dest_for(rel[:-1])
                    dirs[key] = folder_in(parent, rel[-1], True)
                return dirs[key]

            prefix = [top["name"]] if top["mimeType"] == FOLDER else []
            jobs = [(k, dest_for(prefix + rel), "/".join([rname] + prefix + rel + [k["name"]])) for k, rel in files]

            def one(job):
                k, dest, path = job
                t = name_taken(dest, k["name"])
                if t is None:
                    st = "error"
                elif t:
                    st, cid = "skip_exists", ""
                else:
                    c = gws(["copy", "--params", json.dumps({"fileId": k["id"], "fields": "id,md5Checksum,parents"}),
