                    cid = c.get("id", "") if isinstance(c, dict) else ""
                    if not cid or c.get("parents") != [dest]:
                        st = "error"
                    elif k.get("md5Checksum"):
                        st = "copied" if c.get("md5Checksum") == k["md5Checksum"] else "error"
                    else:
                        st = "copied_unverified"
                log([k["id"], st, cid if st != "error" else "", path])
                return st

            with ThreadPoolExecutor(8) as ex:   # folders were made above, serially; only file copies run in parallel
                for st in ex.map(one, jobs):
                    totals[st] = totals.get(st, 0) + 1
    print(totals, "->", LOG if apply else "(dry run)")


