#!/usr/bin/env python3
"""Trash the two old DEV backups in Drive's "Computers" (plan Task 14, Eric chose A on Decision Desk
2026-11-03-computers-dev-backups). Drive Trash keeps items 30 days.

  python3 -I tools/trash_computers_dev.py            # dry run: what would be trashed, kept, skipped (changes nothing)
  python3 -I tools/trash_computers_dev.py --apply    # trash, log

Targets: exactly the folders named DEV directly inside the device roots "My Mac" and "My Laptop (2)" (ids from the
index, each re-read live: name DEV, single parent, that parent a parentless device root with the expected name).
Their code lives in ~/DEV and on GitHub; 26 documents found only there were copied to 10_ARCHIVE/2026/From_Computers
first (copy_log_computers.csv).
Walk (top down, per item): a HEALTH name -> kept, logged by id only, never descended. A file: trashed when mine and not
shared, else kept. A folder: its whole live subtree is scanned (file_moves batching, page() validation); clean = every
item mine, not shared, no HEALTH name, at most 3,000 folders -> the folder is trashed whole; otherwise (a health,
shared or foreign item inside, or too big) the walk goes one level down into it; an odd reply -> skip_check (left).
So health-path and shared items, and their ancestors, stay; everything else goes.
Backups are quiescent (Drive for desktop backups off since 2026-10-23, laptop retired); each trash call follows its
own scan directly. An "intent" row is written before each trash call.
Log: drive-index/trash_log_computers_dev.csv id,status,parent,label (health items: label is the id only).
Statuses: intent, then trashed | unconfirmed; kept_health | kept_shared | skip_check | descend (folder opened).
"""
import argparse, csv, fcntl, json, sqlite3, sys, threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from file_moves import BATCH, FOLDER, HEALTH, OUT, gws, page, parents_q   # noqa: E402

LOG = OUT / "trash_log_computers_dev.csv"
LOCK = OUT / "trash_computers_dev.lock"
TARGETS = {"My Mac", "My Laptop (2)"}


def children(fid):
    out, token, seen = [], None, set()
    while True:
        p = {"q": f"'{fid}' in parents and trashed = false", "pageSize": 1000,
             "fields": "nextPageToken,incompleteSearch,files(id,name,mimeType,shared,ownedByMe)"}
        if token:
            p["pageToken"] = token
        got = page(gws(["list", "--params", json.dumps(p)]), seen)
        if got is None:
            return None
        files, token = got
        out += files
        if not token:
            return out if len({x["id"] for x in out}) == len(out) else None
        seen.add(token)


def mine(f):
    return f.get("shared") is False and f.get("ownedByMe") is True


def clean(fid):
    """True if every item under fid is mine, not shared, no HEALTH name, and the tree has at most 3,000 folders;
    False if any item fails that (or the tree is bigger); None on any odd reply."""
    todo, found, scanned = [fid], {fid}, 0
    while todo:
        batch, todo, token, seen = todo[:BATCH], todo[BATCH:], None, set()
        while True:
            p = {"q": parents_q(batch), "pageSize": 1000,
                 "fields": "nextPageToken,incompleteSearch,files(id,name,mimeType,shared,ownedByMe)"}
            if token:
                p["pageToken"] = token
            got = page(gws(["list", "--params", json.dumps(p)]), seen)
            if got is None:
                return None
            files, token = got
            for f in files:
                if f["id"] in found:
                    return None
                found.add(f["id"])
                if HEALTH.search(f["name"]) or not mine(f):
                    return False
                if f["mimeType"] == FOLDER:
                    todo.append(f["id"])
            if not token:
                break
            seen.add(token)
        scanned += len(batch)
        if scanned > 3000:
            return False                 # too big to trash whole: walk one level down instead
    return True


def targets(con):
    rows = con.execute("select id, folder from files where name = 'DEV' and mime = ? and zone = 'computers' "
                       "and folder like 'Computers/%' and folder not like 'Computers/%/%'", (FOLDER,)).fetchall()
    out = []
    for fid, folder in rows:
        machine = folder.split("/", 1)[1]
        if machine not in TARGETS:
            continue
        m = gws(["get", "--params", json.dumps({"fileId": fid, "fields": "name,parents,trashed"})])
        if not isinstance(m, dict) or m.get("name") != "DEV" or m.get("trashed") is not False \
                or not isinstance(m.get("parents"), list) or len(m["parents"]) != 1:
            raise SystemExit(f"{machine}/DEV does not read live as expected: stop")
        r = gws(["get", "--params", json.dumps({"fileId": m["parents"][0], "fields": "name,parents"})])
        if not isinstance(r, dict) or r.get("name") != machine or "parents" in r:
            raise SystemExit(f"{machine}/DEV: its parent is not the device root {machine}: stop")
        out.append((machine, fid))
    if sorted(m for m, _ in out) != sorted(TARGETS):
        raise SystemExit(f"expected exactly the DEV folders of {sorted(TARGETS)}, found {out}: stop")
    return out


def main(apply):
    if apply:
        lk = open(LOCK, "w")
        try:
            fcntl.flock(lk, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            raise SystemExit("another --apply run holds the lock: stop")
    con = sqlite3.connect(f"file:{OUT / 'drive.sqlite'}?mode=ro", uri=True)
    f = open(LOG, "a", newline="") if apply else None
    w, lock, totals = (csv.writer(f) if f else None), threading.Lock(), {}

    def log(row):
        with lock:
            totals[row[1]] = totals.get(row[1], 0) + 1
            if w:
                w.writerow(row); f.flush()

    def trash(item, parent, label):
        if not apply:
            log([item["id"], "would_trash", parent, label]); return
        log([item["id"], "intent", parent, label])
        t = gws(["update", "--params", json.dumps({"fileId": item["id"], "fields": "trashed"}),
                 "--json", json.dumps({"trashed": True})], tries=1)
        log([item["id"], "trashed" if isinstance(t, dict) and t.get("trashed") is True else "unconfirmed", parent, label])

    def visit(item, parent, label):
        """One child of parent: trash it whole, keep it, or return it for a walk one level down."""
        if HEALTH.search(item["name"]):
            log([item["id"], "kept_health", parent, f"(health item {item['id']})"]); return None
        if not mine(item):
            log([item["id"], "kept_shared", parent, label]); return None
        if item["mimeType"] != FOLDER:
            trash(item, parent, label); return None
        c = clean(item["id"])
        if c is True:
            trash(item, parent, label); return None
        if c is None:
            log([item["id"], "skip_check", parent, label]); return None
        log([item["id"], "descend", parent, label])
        return item

    for machine, root in targets(con):
        level = [(root, f"{machine}/DEV")]
        while level:
            nxt = []
            for fid, label in level:
                kids = children(fid)
                if kids is None:
                    log([fid, "skip_check", "", label]); continue
                with ThreadPoolExecutor(8) as ex:   # siblings are disjoint trees
                    for k, back in zip(kids, ex.map(lambda k: visit(k, fid, f"{label}/{k['name']}"), kids)):
                        if back is not None:
                            nxt.append((k["id"], f"{label}/{k['name']}"))
            level = nxt
    print({k: v for k, v in totals.items() if k != "intent"}, "->", LOG if apply else "(dry run)")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--apply", action="store_true")
    main(ap.parse_args().apply)

